// Loads the Blender-built models (public/models/*.glb, generated by blender/build.py).
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

export async function loadModels() {
  const loader = new GLTFLoader();
  const base = import.meta.env.BASE_URL;
  const [car, nature, gate] = await Promise.all(
    ['car', 'nature', 'gate'].map((n) => loader.loadAsync(`${base}models/${n}.glb`)));
  return { car: car.scene, nature: nature.scene, gate: gate.scene };
}

// The meshes of an object as {geometry, material}, geometry moved into the object's own frame.
export function meshParts(obj) {
  obj.updateMatrixWorld(true);
  const inv = obj.matrixWorld.clone().invert();
  const parts = [];
  obj.traverse((o) => {
    if (!o.isMesh) return;
    const g = o.geometry.clone();
    g.applyMatrix4(new THREE.Matrix4().multiplyMatrices(inv, o.matrixWorld));
    parts.push({ geometry: g, material: o.material });
  });
  return parts;
}

// Soft image-based light for shiny materials (paint, glass, metal), made from the stage's sky colours.
export function makeEnvMap(renderer, env) {
  const scene = new THREE.Scene();
  const top = new THREE.Color(env.sky.top), horizon = new THREE.Color(env.sky.horizon), ground = new THREE.Color(env.ground.a);
  scene.add(new THREE.Mesh(
    new THREE.SphereGeometry(10, 32, 16),
    new THREE.ShaderMaterial({
      side: THREE.BackSide,
      uniforms: { top: { value: top }, horizon: { value: horizon }, ground: { value: ground } },
      vertexShader: 'varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
      fragmentShader: `uniform vec3 top; uniform vec3 horizon; uniform vec3 ground; varying vec3 vP;
        void main(){ float h = normalize(vP).y;
          vec3 c = h > 0.0 ? mix(horizon, top, pow(h, 0.6)) : mix(horizon, ground * 0.6, pow(-h, 0.4));
          gl_FragColor = vec4(c * 1.2, 1.0); }`,
    })));
  const pmrem = new THREE.PMREMGenerator(renderer);
  const tex = pmrem.fromScene(scene, 0.02).texture;
  pmrem.dispose();
  return tex;
}
